struct MarkswiftLineHeight: ViewModifier {
    let factor: CGFloat
    let ascent: CGFloat
    let descent: CGFloat
    let natural: CGFloat
    let halfLeading: Bool
    let compressLines: Bool
    let exactLineBox: Bool
    @ScaledMetric private var size: CGFloat
    @Environment(\.displayScale) private var scale

    init(factor: CGFloat, ascent: CGFloat, descent: CGFloat, natural: CGFloat, halfLeading: Bool, compressLines: Bool, exactLineBox: Bool,
         size: CGFloat, relativeTo style: Font.TextStyle) {
        self.factor = factor
        self.ascent = ascent
        self.descent = descent
        self.natural = natural
        self.halfLeading = halfLeading
        self.compressLines = compressLines
        self.exactLineBox = exactLineBox
        _size = ScaledMetric(wrappedValue: size, relativeTo: style)
    }

    func body(content: Content) -> some View {
        let leading = (factor - natural) * size
        let trim = halfLeading ? 0 : leading / 2
        if #available(iOS 26.0, macOS 26.0, *) {
            // CSS puts the baseline half the leading plus the ascent below the line top; SwiftUI at y = size.
            let shift = (factor / 2 + (ascent - descent) / 2 - 1) * size
            // ponytail: a tight text that wraps only natively (a one-line label under Dynamic Type) keeps natural
            // spacing between its lines, taller than CSS by (natural − factor) × size per extra line.
            // A Text's height is rounded up to the pixel, so the trim is too: the box is exactly the CSS line.
            let tight = factor < natural && !compressLines
            let overflow = tight ? (natural * size * scale).rounded(.up) / scale - factor * size : 0
            MarkswiftLineBox(lineHeight: exactLineBox && !tight ? factor * size : nil, scale: scale) {
                content.lineHeight(.multiple(factor: tight ? natural : factor))
            }.padding(.top, shift - trim)
                .padding(.bottom, -shift - trim - overflow)
        } else {
            content.lineSpacing(max(0, leading)).padding(.vertical, leading / 2 - trim)
        }
    }
}

/// SwiftUI rounds a uniform paragraph's total height up to a device pixel. Keep its natural
/// text frame for painting, but return the fractional CSS line box to the surrounding layout.
private struct MarkswiftLineBox: Layout {
    let lineHeight: CGFloat?
    let scale: CGFloat
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let text = subviews.first else { return .zero }
        var size = text.sizeThatFits(ProposedViewSize(width: proposal.width, height: nil))
        if let lineHeight, lineHeight > 0 {
            let exact = (size.height / lineHeight).rounded() * lineHeight
            let surplus = size.height - exact
            if exact > 0 && surplus >= -0.001 && surplus < 1 / max(1, scale) + 0.001 { size.height = exact }
        }
        return size
    }
    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        subviews.first?.place(at: bounds.origin, proposal: ProposedViewSize(width: bounds.width, height: nil))
    }
}

/// CSS `text-wrap: balance`: the text at the narrowest width that keeps the line count the offered width gives, so its
/// native lines come out about equally long; the frame around it aligns the narrower box as CSS aligns the lines.
struct MarkswiftBalance: Layout {
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let text = subviews.first else { return .zero }
        return text.sizeThatFits(ProposedViewSize(width: Self.width(text, offered: proposal.width), height: nil))
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        subviews.first?.place(at: bounds.origin, proposal: ProposedViewSize(width: bounds.width, height: nil))
    }

    /// Bisects to half a point: the text's height (its line count) at `offered` is the one to keep.
    static func width(_ text: LayoutSubview, offered: CGFloat?) -> CGFloat? {
        guard let offered, offered.isFinite else { return offered }
        let height = text.sizeThatFits(ProposedViewSize(width: offered, height: nil)).height
        var lo: CGFloat = 0
        var hi = offered
        while hi - lo > 0.5 {
            let mid = (lo + hi) / 2
            if text.sizeThatFits(ProposedViewSize(width: mid, height: nil)).height > height + 0.5 { lo = mid } else { hi = mid }
        }
        return hi
    }
}

extension View {
    func markswiftBalance() -> some View { MarkswiftBalance { self } }
}

