/// Apply only axes the installed system face actually exposes, clamped to its declared range.
/// Font.width selects named SF instances; CoreText variation values retain intermediate widths.
nonisolated func markswiftSystemFont(size: CGFloat, weight: CGFloat, design: Font.Design, axes requested: [String: CGFloat]) -> CTFont {
    let index = (0..<9).min { abs(CGFloat($0 + 1) * 100 - weight) < abs(CGFloat($1 + 1) * 100 - weight) } ?? 3
    #if canImport(UIKit)
    let weights: [UIFont.Weight] = [.ultraLight, .thin, .light, .regular, .medium, .semibold, .bold, .heavy, .black]
    let base = UIFont.systemFont(ofSize: size, weight: weights[index])
    let kind: UIFontDescriptor.SystemDesign = design == .serif ? .serif : design == .rounded ? .rounded : design == .monospaced ? .monospaced : .default
    let font = UIFont(descriptor: base.fontDescriptor.withDesign(kind) ?? base.fontDescriptor, size: size) as CTFont
    #else
    let weights: [NSFont.Weight] = [.ultraLight, .thin, .light, .regular, .medium, .semibold, .bold, .heavy, .black]
    let base = NSFont.systemFont(ofSize: size, weight: weights[index])
    let kind: NSFontDescriptor.SystemDesign = design == .serif ? .serif : design == .rounded ? .rounded : design == .monospaced ? .monospaced : .default
    let font = (NSFont(descriptor: base.fontDescriptor.withDesign(kind) ?? base.fontDescriptor, size: size) ?? base) as CTFont
    #endif
    let values = requested.merging(["wght": weight]) { old, _ in old }
    var selected: [Int: CGFloat] = [:]
    for axis in CTFontCopyVariationAxes(font) as? [[CFString: Any]] ?? [] {
        guard let id = axis[kCTFontVariationAxisIdentifierKey] as? Int,
              let lo = axis[kCTFontVariationAxisMinimumValueKey] as? CGFloat,
              let hi = axis[kCTFontVariationAxisMaximumValueKey] as? CGFloat else { continue }
        for (tag, value) in values where tag.utf8.reduce(0, { $0 << 8 | Int($1) }) == id {
            selected[id] = min(hi, max(lo, value))
        }
    }
    guard !selected.isEmpty else { return font }
    let descriptor = CTFontDescriptorCreateWithAttributes([kCTFontVariationAttribute: selected] as CFDictionary)
    return CTFontCreateCopyWithAttributes(font, size, nil, descriptor)
}
extension Font {
    nonisolated static func markswiftSystem(size: CGFloat, weight: CGFloat, design: Font.Design, axes: [String: CGFloat]) -> Font {
        Font(markswiftSystemFont(size: size, weight: weight, design: design, axes: axes))
    }
}

/// Percentage translations follow the final border box without changing its layout slot.
struct MarkswiftResponsiveTranslation: GeometryEffect {
    var width: CGFloat
    var height: CGFloat
    var xWidth: CGFloat
    var xHeight: CGFloat
    var yWidth: CGFloat
    var yHeight: CGFloat

    func effectValue(size: CGSize) -> ProjectionTransform {
        let dw = size.width - width, dh = size.height - height
        return ProjectionTransform(CGAffineTransform(translationX: xWidth * dw + xHeight * dh,
                                                     y: yWidth * dw + yHeight * dh))
    }
}

private struct MarkswiftHitAnchors: PreferenceKey {
    static let defaultValue: [String: Anchor<CGRect>] = [:]
    static func reduce(value: inout [String: Anchor<CGRect>], nextValue: () -> [String: Anchor<CGRect>]) {
        value.merge(nextValue()) { $1 }
    }
}
private struct MarkswiftHitRects: PreferenceKey {
    static let defaultValue: [String: [CGRect]] = [:]
    static func reduce(value: inout [String: [CGRect]], nextValue: () -> [String: [CGRect]]) {
        value.merge(nextValue()) { $1 }
    }
}
private nonisolated struct MarkswiftHitShape: Shape {
    let rects: [CGRect]
    func path(in rect: CGRect) -> Path {
        var path = Path()
        for r in rects { path.addRect(r) }
        return path
    }
}
private struct MarkswiftHitRegion: ViewModifier {
    let id: String
    let targets: [String]
    @State private var rects: [CGRect] = []
    func body(content: Content) -> some View {
        content.backgroundPreferenceValue(MarkswiftHitAnchors.self) { anchors in
            GeometryReader { proxy in
                Color.clear.preference(key: MarkswiftHitRects.self,
                    value: [id: targets.compactMap { anchors[$0].map { proxy[$0] } }])
            }.allowsHitTesting(false)
        }
        .onPreferenceChange(MarkswiftHitRects.self) { rects = $0[id] ?? [] }
        .contentShape(MarkswiftHitShape(rects: rects))
    }
}
extension View {
    func markswiftHitTarget(_ id: String) -> some View {
        anchorPreference(key: MarkswiftHitAnchors.self, value: .bounds) { [id: $0] }
    }
    func markswiftHitRegion(_ id: String, targets: [String]) -> some View {
        modifier(MarkswiftHitRegion(id: id, targets: targets))
    }
}


/// Plain wrapping paragraphs use UIKit's public word-wrap strategy on iOS 26+; SwiftUI Text
/// enables orphan avoidance with no public switch. Rich runs retain the SwiftUI text pipeline.
struct MarkswiftGreedyText: View {
    let text: String
    let font: Font
    let color: Color
    let size: CGFloat
    let style: Font.TextStyle
    let lineHeight: CGFloat
    let ascent: CGFloat
    let descent: CGFloat
    let natural: CGFloat
    var lineLimit: Int? = nil
    var body: some View {
        #if os(iOS)
        if #available(iOS 26.0, *) {
            MarkswiftGreedyLabel(text: text, font: font, color: color, size: size, lineHeight: lineHeight, ascent: ascent, descent: descent, lineLimit: lineLimit)
        } else { fallback }
        #else
        fallback
        #endif
    }
    private var fallback: some View {
        Text(verbatim: text).font(font).foregroundStyle(color)
            .lineLimit(lineLimit)
            .fixedSize(horizontal: false, vertical: true)
            .markswiftLineHeight(lineHeight, size: size, relativeTo: style,
                                 ascent: ascent, descent: descent, natural: natural)
    }
}
#if os(iOS)
@available(iOS 26.0, *)
private struct MarkswiftGreedyLabel: UIViewRepresentable {
    let text: String
    let font: Font
    let color: Color
    let size: CGFloat
    let lineHeight: CGFloat
    let ascent: CGFloat
    let descent: CGFloat
    let lineLimit: Int?
    func makeUIView(context: Context) -> UILabel {
        let label = UILabel()
        label.setContentCompressionResistancePriority(.defaultLow, for: .horizontal)
        return label
    }
    func updateUIView(_ label: UILabel, context: Context) {
        label.numberOfLines = lineLimit ?? 0
        label.lineBreakMode = lineLimit == nil ? .byWordWrapping : .byTruncatingTail
        let resolved = font.resolve(in: context.environment.fontResolutionContext)
        let paragraph = NSMutableParagraphStyle()
        paragraph.lineBreakMode = .byWordWrapping
        paragraph.lineBreakStrategy = []
        paragraph.minimumLineHeight = lineHeight * resolved.pointSize / size
        paragraph.maximumLineHeight = paragraph.minimumLineHeight
        // A fixed-height UIKit paragraph places its baseline above the rounded native descent.
        // CSS splits the extra leading around the rounded captured ascent/descent instead.
        let scale = context.environment.displayScale
        let nativeDescent = (CTFontGetDescent(resolved.ctFont) * scale).rounded(.down) / scale
        let cssBaseline = (lineHeight / size + ascent - descent) * resolved.pointSize / 2
        let baselineOffset = paragraph.minimumLineHeight - nativeDescent - cssBaseline
        let rgba = color.resolve(in: context.environment)
        label.attributedText = NSAttributedString(string: text, attributes: [
            .font: resolved.ctFont,
            .foregroundColor: UIColor(red: CGFloat(rgba.red), green: CGFloat(rgba.green), blue: CGFloat(rgba.blue), alpha: CGFloat(rgba.opacity)),
            .paragraphStyle: paragraph,
            .baselineOffset: baselineOffset,
        ])
        label.accessibilityLabel = text
    }
    func sizeThatFits(_ proposal: ProposedViewSize, uiView: UILabel, context: Context) -> CGSize? {
        uiView.sizeThatFits(CGSize(width: proposal.width ?? CGFloat.greatestFiniteMagnitude, height: CGFloat.greatestFiniteMagnitude))
    }
}
#endif


/// CSS relative positioning moves paint after text layout; adjacent runs retain their advances.
struct MarkswiftTextOffset: TextAttribute {
    let x: CGFloat
    let y: CGFloat
}

struct MarkswiftOffsetTextRenderer: TextRenderer {
    let x: CGFloat
    let y: CGFloat
    var displayPadding: EdgeInsets { EdgeInsets(top: y, leading: x, bottom: y, trailing: x) }
    func draw(layout: Text.Layout, in context: inout GraphicsContext) {
        for line in layout {
            for run in line {
                var copy = context
                if let offset = run[MarkswiftTextOffset.self] {
                    copy.translateBy(x: offset.x, y: offset.y)
                }
                copy.draw(run)
            }
        }
    }
}


// `UTType` (the file importer's content types) is not re-exported by SwiftUI or Foundation.
import UniformTypeIdentifiers

/// A URL from a design's `href`. Anything the design left unresolvable (an in-page anchor, a
/// relative path, a malformed URL) becomes `about:blank` rather than trapping at runtime.
nonisolated func markswiftURL(_ s: String) -> URL {
    URL(string: s) ?? URL(string: "about:blank")!
}

/// The types an `<input type="file" accept>` list names. The tokens are the attribute's own
/// forms — `.png`, `image/png`, `image/*` — and only the running system knows what they mean,
/// so they are resolved here rather than at generation time. A token the system does not
/// recognise is dropped, and a list that resolves to nothing means "any file".
nonisolated func markswiftContentTypes(_ accept: String) -> [UTType] {
    var out: [UTType] = []
    for token in accept.split(separator: ",") {
        let name = String(token.filter { !$0.isWhitespace }).lowercased()
        if name.isEmpty { continue }
        let type: UTType?
        if name.hasPrefix(".") {
            type = UTType(filenameExtension: String(name.dropFirst()))
        } else if name.hasSuffix("/*") {
            switch String(name.dropLast(2)) {
            case "image": type = .image
            case "audio": type = .audio
            case "video": type = .movie
            case "text": type = .text
            default: type = .item
            }
        } else {
            type = UTType(mimeType: name)
        }
        if let type, !out.contains(type) { out.append(type) }
    }
    return out.isEmpty ? [.item] : out
}

/// One radio of a group: on when the group's selection is this radio's tag; turning it on selects it.
/// A lone radio binds its `Bool` with tag `true`: a tap selects it and nothing clears it.
extension Binding where Value: Equatable & Sendable {
    func markswiftSelects(_ tag: Value) -> Binding<Bool> {
        Binding<Bool>(get: { wrappedValue == tag }, set: { if $0 { wrappedValue = tag } })
    }
}

/// The keyboard, autofill type, capitalisation and Return key iOS Safari gives the same `<input>`.
/// These modifiers exist only on iOS; on other platforms (the macOS render gate) the field is unchanged.
nonisolated enum MarkswiftInputTraits: Sendable { case email, tel, url, number, search, password }

extension View {
