/// The checkbox and radio HTML draws: a small square or circle that fills with the tint when on.
/// iOS has no native checkbox, and a switch does not fit the box the design measured.
nonisolated struct MarkswiftMarkToggleStyle: ToggleStyle {
    enum Mark { case check, dot }
    let mark: Mark
    let tint: Color

    func makeBody(configuration: Configuration) -> some View {
        Button {
            configuration.isOn.toggle()
        } label: {
            ZStack {
                box(on: configuration.isOn)
                if configuration.isOn { fill }
            }
        }
        .buttonStyle(PlainButtonStyle())
    }

    @ViewBuilder private func box(on: Bool) -> some View {
        let face = on ? tint : Color.markswiftSystemBackground
        let line = on ? tint : Color.markswiftSystemGray2
        switch mark {
        case .check:
            RoundedRectangle(cornerRadius: 2, style: .circular)
                .fill(face)
                .overlay(RoundedRectangle(cornerRadius: 2, style: .circular).strokeBorder(line, lineWidth: 1))
        case .dot:
            Circle()
                .fill(on ? Color.clear : face)
                .overlay(Circle().strokeBorder(line, lineWidth: on ? 2 : 1))
        }
    }

    @ViewBuilder private var fill: some View {
        switch mark {
        case .check:
            Image(systemName: "checkmark")
                .resizable()
                .scaledToFit()
                .fontWeight(.bold)
                .foregroundStyle(Color.markswiftSystemBackground)
                .padding(2)
        case .dot:
            Circle().fill(tint).padding(3)
        }
    }
}

/// The bar a browser paints for `<progress>`/`<meter>`: a rounded track with the completed part
/// filled, centred in the element's box.
nonisolated struct MarkswiftBar: View {
    let fraction: Double
    let height: CGFloat
    let tint: Color
    let track: Color
    let edge: Color

    var body: some View {
        GeometryReader { geo in
            ZStack(alignment: .leading) {
                Capsule().fill(track)
                Capsule().fill(tint).frame(width: geo.size.width * min(max(fraction, 0), 1))
            }
            .overlay(Capsule().strokeBorder(edge, lineWidth: 1))
            .frame(height: height)
            .frame(maxHeight: .infinity, alignment: .center)
        }
    }
}

nonisolated struct MarkswiftBarProgressStyle: ProgressViewStyle {
    let height: CGFloat
    let tint: Color
    let track: Color
    let edge: Color

    func makeBody(configuration: Configuration) -> some View {
        // No value: the browser draws a short pulse near the start of the track.
        MarkswiftBar(fraction: configuration.fractionCompleted ?? 0.25, height: height, tint: tint, track: track, edge: edge)
    }
}

nonisolated struct MarkswiftBarGaugeStyle: GaugeStyle {
    let height: CGFloat
    let tint: Color
    let track: Color
    let edge: Color

    func makeBody(configuration: Configuration) -> some View {
        MarkswiftBar(fraction: configuration.value, height: height, tint: tint, track: track, edge: edge)
    }
}

/// A range input as the browser paints it: a half-height track filled up to the value, with a
/// round thumb on it. `ImageRenderer` cannot rasterise a live `Slider`, so the fidelity views
/// use this to verify the design's geometry.
nonisolated struct MarkswiftSliderTrack: View {
    let fraction: Double
    let height: CGFloat
    let tint: Color
    let track: Color
    let edge: Color

    var body: some View {
        GeometryReader { geo in
            let thumb = height * 0.875
            let usable = max(geo.size.width - thumb, 0)
            ZStack(alignment: .leading) {
                MarkswiftBar(fraction: fraction, height: height / 2, tint: tint, track: track, edge: edge)
                Circle()
                    .fill(tint)
                    .frame(width: thumb, height: thumb)
                    .offset(x: usable * min(max(fraction, 0), 1))
            }
            .frame(maxHeight: .infinity, alignment: .center)
        }
    }
}

/// `<details>` as the browser draws it: the captured `<summary>` (its `::marker` included) is the
/// whole tap target, the content follows at the measured gap, and there is no system chevron. `open`/`close`: the
/// content's CSS height animation, played as a `MarkswiftReveal`; nil for both = it snaps.
nonisolated struct MarkswiftDisclosureStyle: DisclosureGroupStyle {
    let spacing: CGFloat
    var open: Animation? = nil, close: Animation? = nil

    func makeBody(configuration: Configuration) -> some View {
        VStack(alignment: .leading, spacing: spacing) {
            Button {
                withAnimation(configuration.isExpanded ? close : open) { configuration.isExpanded.toggle() }
            } label: {
                configuration.label.contentShape(Rectangle())
            }
            .buttonStyle(PlainButtonStyle())
            .accessibilityValue(configuration.isExpanded ? Text("Expanded") : Text("Collapsed"))
            if configuration.isExpanded {
                if open != nil || close != nil {
                    configuration.content
                        .transition(.modifier(active: MarkswiftReveal(fraction: 0), identity: MarkswiftReveal(fraction: 1)))
                } else {
                    configuration.content
                }
            }
        }
    }
}

extension Date {
    /// A date/time `<input>` value as the wall-clock time the design wrote, in the user's time zone.
    nonisolated static func markswift(year: Int, month: Int, day: Int, hour: Int, minute: Int, second: Int) -> Date {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = .current
        return calendar.date(from: DateComponents(year: year, month: month, day: day, hour: hour, minute: minute, second: second)) ?? .now
    }
}

extension View {
    /// `TextEditor` insets its text inside its frame (UITextView: 8 pt above and below, 5 pt line
    /// fragment padding at the sides); the CSS padding already placed it, so the editor overhangs
    /// its frame by exactly those insets.
    // ponytail: UIKit default insets as constants; recalibrate from an iOS render if an SDK changes them.
    @ViewBuilder func markswiftTextEditorInsets() -> some View {
        #if os(iOS)
        padding(EdgeInsets(top: -8, leading: -5, bottom: -8, trailing: -5))
        #else
        self
        #endif
    }

    /// App mode: an editor as tall as `text` laid out at its width and font (CSS `field-sizing: content`), so it grows
    /// with its text and with Dynamic Type; `TextEditor` alone takes whatever height it is offered. A trailing newline
    /// still opens an empty line, as it does in the editor.
    func markswiftFitsText(_ text: String) -> some View {
        Text(verbatim: text.isEmpty || text.hasSuffix("\n") ? text + " " : text)
            .fixedSize(horizontal: false, vertical: true)
            .frame(maxWidth: .infinity, alignment: .leading)
            .hidden()
            .overlay { self }
    }

    /// App mode: CSS `line-height` on a text field or editor whose text is `size` points, scaling like a font
    /// `relativeTo: style`. The leading over the face's natural line (default: SF Pro, 2444 per 2048) spaces an editor's
    /// lines and, as half-leading, pads its text above the first line and below the last (an editor's text starts at its
    /// top, where the browser's first line box does); `face` names an editor's bundled family (nil: the system font).
    /// A field's single line is centred, and at the default size the captured box already holds it (Chrome centres it
    /// in a shorter input, too): only what Dynamic Type adds pads it.
    func markswiftFieldLineHeight(_ lineHeight: CGFloat, size: CGFloat, relativeTo style: Font.TextStyle,
                                  natural: CGFloat = 2444.0 / 2048, editor: Bool = false, face: String? = nil, capturedHeight: CGFloat? = nil) -> some View {
        modifier(MarkswiftFieldLineHeight(factor: lineHeight / size, natural: natural, base: size, editor: editor, face: face,
                                          relativeTo: style, capturedHeight: capturedHeight))
    }
}

struct MarkswiftFieldLineHeight: ViewModifier {
    let factor: CGFloat
    let natural: CGFloat
    let base: CGFloat
    let editor: Bool
    let face: String?
    let capturedHeight: CGFloat?
    @Environment(\.displayScale) private var scale
    @ScaledMetric private var size: CGFloat

    init(factor: CGFloat, natural: CGFloat, base: CGFloat, editor: Bool, face: String?, relativeTo style: Font.TextStyle, capturedHeight: CGFloat?) {
        self.factor = factor
        self.natural = natural
        self.base = base
        self.editor = editor
        self.face = face
        self.capturedHeight = capturedHeight
        _size = ScaledMetric(wrappedValue: base, relativeTo: style)
    }

    func body(content: Content) -> some View {
        let leading = max(0, factor - natural)
        let half = leading * (editor ? size : max(0, size - base)) / 2
        // The editor draws its first line lower by its tall glyphs; the top pad gives that back, the bottom keeps the box.
        let tall = editor ? markswiftTallGlyphs(face, size) : 0
        if editor || capturedHeight == nil {
            content.lineSpacing(leading * size).padding(.top, half - tall).padding(.bottom, half + tall)
        } else {
            MarkswiftFieldBox(height: capturedHeight, scale: scale) {
                content.lineSpacing(leading * size)
            }.padding(.top, half).padding(.bottom, half)
        }
    }
}

/// A single-line native field can round its intrinsic height up by one device pixel beyond
/// the captured content box. Remove only that surplus; larger Dynamic Type growth stays native.
private struct MarkswiftFieldBox: Layout {
    let height: CGFloat?
    let scale: CGFloat
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let field = subviews.first else { return .zero }
        var size = field.sizeThatFits(ProposedViewSize(width: proposal.width, height: nil))
        if let height, height > 0 {
            let surplus = size.height - height
            if surplus >= 0 && surplus <= 1 / max(1, scale) + 0.001 { size.height = height }
        }
        return size
    }
    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        guard let field = subviews.first else { return }
        let offered = ProposedViewSize(width: bounds.width, height: nil)
        let natural = field.sizeThatFits(offered)
        field.place(at: CGPoint(x: bounds.minX, y: bounds.midY - natural.height / 2), proposal: offered)
    }
}

/// How far iOS's text view (`TextEditor`) sets its first baseline below the face's ascent: to the top of the font's
/// bounding box when glyphs rise above the ascent (Geist: 1058 over 1005 per 1000; SF Pro's box stays below it).
// ponytail: rule measured on iOS 27 with Geist (shadcn-textarea) and SF Pro (tw-form); re-measure if a face disagrees.
nonisolated func markswiftTallGlyphs(_ face: String?, _ size: CGFloat) -> CGFloat {
    #if os(iOS)
    let font = face.map {
        CTFontCreateWithFontDescriptor(
            CTFontDescriptorCreateWithAttributes([kCTFontFamilyNameAttribute: $0] as CFDictionary), size, nil)
    } ?? CTFontCreateUIFontForLanguage(.system, size, nil)
    guard let font else { return 0 }
    let box = CTFontGetBoundingBox(font)
    return max(0, box.origin.y + box.size.height - CTFontGetAscent(font))
    #else
    return 0
    #endif
}

/// Interaction states a render harness forces on every element at once (the browser reference forces the same).
nonisolated struct MarkswiftForcedStates: OptionSet, Sendable {
    let rawValue: Int
    static let pressed = MarkswiftForcedStates(rawValue: 1)
    static let focused = MarkswiftForcedStates(rawValue: 2)
    /// Reduce Motion for harnesses (`accessibilityReduceMotion` has no public setter).
    static let reduceMotion = MarkswiftForcedStates(rawValue: 4)
}

extension EnvironmentValues {
    @Entry var markswiftForcedStates: MarkswiftForcedStates = []
}

/// Whether one design element is pressed: the live press (bound by `MarkswiftPressStyle`), or forced by a harness.
@propertyWrapper struct MarkswiftPressed: DynamicProperty {
    @State private var live = false
    @Environment(\.markswiftForcedStates) private var forced
    init() {}
    var wrappedValue: Bool { live || forced.contains(.pressed) }
    var projectedValue: Binding<Bool> { $live }
}

/// Whether one text field has focus: the live focus (bound with `.focused($…)`), or forced by a harness. Setting it
/// moves the live focus (a `<label>` tap).
@propertyWrapper struct MarkswiftFocused: DynamicProperty {
    @FocusState private var live: Bool
    @Environment(\.markswiftForcedStates) private var forced
    init() {}
    var wrappedValue: Bool {
        get { live || forced.contains(.focused) }
        nonmutating set { live = newValue }
    }
    var projectedValue: FocusState<Bool>.Binding { $live }
}

/// A plain button that reports its press, so the label can draw the design's pressed look instead of system dimming.
nonisolated struct MarkswiftPressStyle: ButtonStyle {
    let isPressed: Binding<Bool>
    func makeBody(configuration: Configuration) -> some View {
        configuration.label.onChange(of: configuration.isPressed) { _, pressed in isPressed.wrappedValue = pressed }
    }
}


struct MarkswiftMeasuredLayout: Layout {
    var width: CGFloat
    var height: CGFloat
    var frames: [CGRect]
    /// App mode: a child taller than its captured frame (Dynamic Type) moves every frame wholly below it down by the
    /// difference, and the layout grows with its lowest frame. Fidelity keeps the captured frames.
    var grows = false

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard grows else { return CGSize(width: width, height: height) }
        let bottom = frames.map(\.maxY).max() ?? 0
        let grown = placed(subviews).map(\.maxY).max() ?? 0
        return CGSize(width: width, height: height + max(0, grown - bottom))
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        for (index, (subview, frame)) in zip(subviews, grows ? placed(subviews) : frames).enumerated() where index < frames.count {
            subview.place(at: CGPoint(x: bounds.minX + frame.minX, y: bounds.minY + frame.minY),
                          anchor: .topLeading, proposal: ProposedViewSize(width: frame.width, height: frame.height))
        }
    }

    /// Captured frames at the children's native heights, top to bottom: each moves down by the most any frame above it moved
    /// or grew. ponytail: O(n²) over the children; measured layouts hold a handful.
    private func placed(_ subviews: Subviews) -> [CGRect] {
        var out = frames
        for i in frames.indices.sorted(by: { frames[$0].minY < frames[$1].minY }) where i < subviews.count {
            let f = frames[i]
            let shift = frames.indices.filter { $0 != i && frames[$0].maxY <= f.minY + 0.5 }.map { out[$0].maxY - frames[$0].maxY }.max() ?? 0
            let fitted = subviews[i].sizeThatFits(ProposedViewSize(width: f.width, height: nil)).height
            out[i] = CGRect(x: f.minX, y: f.minY + max(0, shift), width: f.width, height: max(f.height, fitted))
        }
        return out
    }
}


struct MarkswiftFlow: Layout {
    var columnGap: CGFloat
    var rowGap: CGFloat
    var horizontal: HorizontalAlignment = .leading
    var vertical: VerticalAlignment = .top

    private struct Item {
        var index: Int
        var size: CGSize
    }

    private struct Row {
        var items: [Item] = []
        var width: CGFloat = 0
        var height: CGFloat = 0
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let available = finiteWidth(proposal.width)
        let rows = rows(width: available ?? .infinity, subviews: subviews)
        let width = available ?? rows.map { $0.width }.max() ?? 0
        let height = rows.reduce(CGFloat(0)) { $0 + $1.height } + CGFloat(max(0, rows.count - 1)) * rowGap
        return CGSize(width: width, height: height)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let rows = rows(width: max(0, bounds.width), subviews: subviews)
        var y = bounds.minY
        for row in rows {
            let remaining = bounds.width - row.width
            var x = bounds.minX + (horizontal == .center ? remaining / 2 : horizontal == .trailing ? remaining : 0)
            for item in row.items {
                let slack = row.height - item.size.height
                let dy = vertical == .center ? slack / 2 : vertical == .bottom ? slack : 0
                subviews[item.index].place(at: CGPoint(x: x, y: y + dy), anchor: .topLeading,
                                          proposal: ProposedViewSize(width: item.size.width, height: item.size.height))
                x += item.size.width + columnGap
            }
            y += row.height + rowGap
        }
    }

    private func finiteWidth(_ value: CGFloat?) -> CGFloat? {
        guard let value, value.isFinite else { return nil }
        return max(0, value)
    }

    private func rows(width: CGFloat, subviews: Subviews) -> [Row] {
        var result: [Row] = []
        var row = Row()
        for (index, subview) in subviews.enumerated() {
            var measured = subview.sizeThatFits(.unspecified)
            // CSS shrinks an item wider than the line down to the line (flex-shrink: 1); text re-wraps instead of overflowing.
            if measured.width > width { measured = subview.sizeThatFits(ProposedViewSize(width: width, height: nil)) }
            let size = CGSize(width: measured.width.isFinite ? max(0, measured.width) : 0,
                              height: measured.height.isFinite ? max(0, measured.height) : 0)
            let gap = row.items.isEmpty ? 0 : columnGap
            if !row.items.isEmpty && row.width + gap + size.width > width + 0.0001 {
                result.append(row)
                row = Row()
            }
            row.width += (row.items.isEmpty ? 0 : columnGap) + size.width
            row.height = max(row.height, size.height)
            row.items.append(Item(index: index, size: size))
        }
        if !row.items.isEmpty { result.append(row) }
        return result
    }
}


/// `fr(f, min:)`: `minmax(<min>px, <f>fr)`; a bare fr track has no floor.
enum MarkswiftTrack: Sendable { case px(CGFloat), fr(CGFloat, min: CGFloat = 0), auto }
enum MarkswiftAutoRepeat: Sendable { case fill(min: CGFloat), fit(min: CGFloat) }
/// A grid row: `auto` (also `min-content`/`max-content`) is as tall as its items, `px` is fixed.
nonisolated enum MarkswiftRow: Sendable, Equatable { case auto, px(CGFloat) }
/// `justify-self` inside the cell's column span; `stretch` takes the span's width.
nonisolated enum MarkswiftJustify: Sendable { case stretch, start, center, end }

/// A cell's CSS grid area in 1-based lines (spans count tracks), resolved from the capture (areas included).
nonisolated struct MarkswiftGridCell: Sendable, Equatable {
    var column: Int
    var row: Int
    var columnSpan: Int = 1
    var rowSpan: Int = 1
    var justify: MarkswiftJustify = .stretch
}

/// Read by `MarkswiftTracks`; a subview without it takes the next row-major cell.
nonisolated struct MarkswiftGridCellKey: LayoutValueKey { static let defaultValue: MarkswiftGridCell? = nil }

extension View {
    /// Places this view in a `MarkswiftTracks` grid area (CSS `grid-column`/`grid-row`/`justify-self`).
    func markswiftGridCell(column: Int, row: Int, columnSpan: Int = 1, rowSpan: Int = 1,
                           justify: MarkswiftJustify = .stretch) -> some View {
        layoutValue(key: MarkswiftGridCellKey.self,
                    value: MarkswiftGridCell(column: column, row: row, columnSpan: columnSpan, rowSpan: rowSpan, justify: justify))
    }
}

/// CSS grid column tracks (px / fr / auto, or repeat(auto-fill|auto-fit, minmax(min, 1fr))), auto/px rows, and
/// cells placed row-major or by `markswiftGridCell`.
struct MarkswiftTracks: Layout {
    var tracks: [MarkswiftTrack] = []
    var autoRepeat: MarkswiftAutoRepeat? = nil
    /// Explicit rows (`grid-template-rows`); rows past them are `autoRow` (`grid-auto-rows`).
    var rows: [MarkswiftRow] = []
    var autoRow: MarkswiftRow = .auto
    var hSpacing: CGFloat
    var vSpacing: CGFloat
    /// align-items stretch: every cell is proposed its row span's height.
    var stretch: Bool = true

    /// Pure column solver; `MarkswiftTracks.columns` and `solveTracks` (src/analysis/grid-tracks.ts) must agree.
    static func columns(width: CGFloat, tracks: [MarkswiftTrack], autoRepeat: MarkswiftAutoRepeat?, count: Int,
                        spacing: CGFloat, autoWidths: [CGFloat]) -> [CGFloat] {
        if let autoRepeat {
            let (min, fit): (CGFloat, Bool) = switch autoRepeat {
            case .fill(let min): (min, false)
            case .fit(let min): (min, true)
            }
            var n = max(1, Int(((width + spacing) / (min + spacing)).rounded(.down)))
            if fit { n = Swift.min(n, max(1, count)) } // auto-fit collapses empty tracks
            return Array(repeating: max(0, (width - CGFloat(n - 1) * spacing) / CGFloat(n)), count: n)
        }
        var sizes = [CGFloat](repeating: 0, count: tracks.count)
        var open = [Bool](repeating: false, count: tracks.count)
        for (c, t) in tracks.enumerated() {
            switch t {
            case .px(let v): sizes[c] = v
            case .fr(_, let floor): sizes[c] = floor; open[c] = true
            case .auto: sizes[c] = c < autoWidths.count ? autoWidths[c] : 0
            }
        }
        // CSS "find the size of an fr": a floor above its share freezes the track; the rest share again.
        var changed = true
        while changed {
            changed = false
            let free = width - CGFloat(tracks.count - 1) * spacing - tracks.indices.map { open[$0] ? 0 : sizes[$0] }.reduce(0, +)
            var frs: CGFloat = 0
            for (c, t) in tracks.enumerated() where open[c] { if case .fr(let f, _) = t { frs += f } }
            let unit = max(0, free) / max(1, frs)
            for (c, t) in tracks.enumerated() where open[c] {
                guard case .fr(let f, let floor) = t else { continue }
                if unit * f < floor {
                    open[c] = false
                    sizes[c] = floor
                    changed = true
                } else { sizes[c] = unit * f }
            }
        }
        return sizes
    }

    /// Pure row solver; `MarkswiftTracks.rowHeights` and `solveRows` (src/analysis/grid-tracks.ts) must agree.
    /// `items`: each cell's 1-based start row, row span and margin-box height. CSS grid §12.5 for heights: a spanning
    /// cell's missing height goes equally to its spanned auto rows no cell has sized yet, else to all of its spanned
    /// auto rows; cells of the same span take the largest share per row, smaller spans first.
    static func rowHeights(rows: [MarkswiftRow], autoRow: MarkswiftRow, spacing: CGFloat,
                           items: [(row: Int, span: Int, height: CGFloat)]) -> [CGFloat] {
        let count = max(rows.count, items.map { $0.row + $0.span - 1 }.max() ?? 0)
        let defs = (0..<count).map { $0 < rows.count ? rows[$0] : autoRow }
        var sizes = defs.map { def -> CGFloat in if case .px(let v) = def { v } else { 0 } }
        var open = defs.map { $0 == .auto }
        for item in items where item.span == 1 && defs[item.row - 1] == .auto {
            sizes[item.row - 1] = max(sizes[item.row - 1], item.height)
            open[item.row - 1] = false
        }
        for span in Set(items.map(\.span).filter { $0 > 1 }).sorted() {
            var planned = [CGFloat](repeating: 0, count: count)
            for item in items where item.span == span {
                let range = (item.row - 1)..<(item.row - 1 + span)
                let extra = item.height - range.map { sizes[$0] }.reduce(0, +) - CGFloat(span - 1) * spacing
                let auto = range.filter { defs[$0] == .auto }
                let targets = auto.contains { open[$0] } ? auto.filter { open[$0] } : auto
                if extra > 0 { for r in targets { planned[r] = max(planned[r], extra / CGFloat(targets.count)) } }
            }
            for r in planned.indices where planned[r] > 0 {
                sizes[r] += planned[r]
                open[r] = false
            }
        }
        return sizes
    }

    /// Each subview's cell: its `markswiftGridCell`, else the next row-major cell of `count` columns.
    private func cells(_ subviews: Subviews, _ count: Int) -> [MarkswiftGridCell] {
        subviews.indices.map { subviews[$0][MarkswiftGridCellKey.self] ?? MarkswiftGridCell(column: $0 % count + 1, row: $0 / count + 1) }
    }

    /// Size of `count` tracks from 0-based `start`, gaps between them included.
    private static func extent(_ sizes: [CGFloat], _ start: Int, _ count: Int, _ gap: CGFloat) -> CGFloat {
        let lo = min(start, sizes.count), hi = min(start + count, sizes.count)
        return sizes[lo..<hi].reduce(0, +) + CGFloat(max(0, hi - lo - 1)) * gap
    }

    /// The widest ideal width among single-column cells in column `c` (`ideal` per subview).
    private func widest(_ c: Int, _ at: [MarkswiftGridCell], _ ideal: [CGFloat]) -> CGFloat {
        at.indices.filter { at[$0].column == c + 1 && at[$0].columnSpan == 1 }.map { ideal[$0] }.max() ?? 0
    }

    private func columns(_ width: CGFloat, _ subviews: Subviews) -> [CGFloat] {
        let at = cells(subviews, max(1, tracks.count))
        let ideal = subviews.map { $0.sizeThatFits(.unspecified).width }
        let autoWidths = tracks.indices.map { c -> CGFloat in
            guard case .auto = tracks[c] else { return 0 }
            return widest(c, at, ideal)
        }
        return Self.columns(width: width, tracks: tracks, autoRepeat: autoRepeat, count: subviews.count,
                            spacing: hSpacing, autoWidths: autoWidths)
    }

    /// Without a finite width every column takes its content's ideal width (fr and auto-repeat columns included).
    private func idealColumns(_ subviews: Subviews) -> [CGFloat] {
        let ideal = subviews.map { $0.sizeThatFits(.unspecified).width }
        if autoRepeat != nil { return Array(repeating: ideal.max() ?? 0, count: max(1, subviews.count)) }
        let at = cells(subviews, max(1, tracks.count))
        return tracks.indices.map { c in
            if case .px(let v) = tracks[c] { return v }
            return widest(c, at, ideal)
        }
    }

    /// Cells, each cell's width inside its column span (`justify`), and the row heights.
    private func arrange(_ cols: [CGFloat], _ subviews: Subviews) -> (cells: [MarkswiftGridCell], widths: [CGFloat], rows: [CGFloat]) {
        let at = cells(subviews, cols.count)
        let widths = subviews.indices.map { i -> CGFloat in
            let span = Self.extent(cols, at[i].column - 1, at[i].columnSpan, hSpacing)
            if at[i].justify == .stretch { return span }
            return min(span, subviews[i].sizeThatFits(ProposedViewSize(width: span, height: nil)).width)
        }
        let items = subviews.indices.map { i in
            (row: at[i].row, span: at[i].rowSpan,
             height: subviews[i].sizeThatFits(ProposedViewSize(width: widths[i], height: nil)).height)
        }
        return (at, widths, Self.rowHeights(rows: rows, autoRow: autoRow, spacing: vSpacing, items: items))
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let finite = proposal.width.flatMap { $0.isFinite ? max(0, $0) : nil }
        let cols = finite.map { columns($0, subviews) } ?? idealColumns(subviews)
        let r = arrange(cols, subviews).rows
        let width = finite ?? Self.extent(cols, 0, cols.count, hSpacing)
        return CGSize(width: width, height: Self.extent(r, 0, r.count, vSpacing))
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let cols = columns(bounds.width, subviews)
        let (at, widths, r) = arrange(cols, subviews)
        for i in subviews.indices {
            let cell = at[i]
            let span = Self.extent(cols, cell.column - 1, cell.columnSpan, hSpacing)
            let dx = cell.justify == .end ? span - widths[i] : cell.justify == .center ? (span - widths[i]) / 2 : 0
            let x = bounds.minX + Self.extent(cols, 0, cell.column - 1, hSpacing) + (cell.column > 1 ? hSpacing : 0) + dx
            let y = bounds.minY + Self.extent(r, 0, cell.row - 1, vSpacing) + (cell.row > 1 ? vSpacing : 0)
            let h = Self.extent(r, cell.row - 1, cell.rowSpan, vSpacing)
            subviews[i].place(at: CGPoint(x: x, y: y), anchor: .topLeading,
                              proposal: ProposedViewSize(width: widths[i], height: stretch ? h : nil))
        }
    }
}

/// CSS percentage width: the child takes `fraction` of the proposed width, aligned to the containing block's start edge; the wrapper keeps the full width.
struct MarkswiftFraction: Layout {
    var fraction: CGFloat
    var right: Bool = false

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let width = proposal.width, width.isFinite else { return subviews.first?.sizeThatFits(.unspecified) ?? .zero }
        let h = subviews.first?.sizeThatFits(ProposedViewSize(width: width * fraction, height: proposal.height)).height ?? 0
        return CGSize(width: width, height: h)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let x = bounds.minX + (right ? bounds.width * (1 - fraction) : 0)
        subviews.first?.place(at: CGPoint(x: x, y: bounds.minY), anchor: .topLeading,
                              proposal: ProposedViewSize(width: bounds.width * fraction, height: bounds.height))
    }
}

extension View {
    /// CSS percentage width: the box takes `fraction` of its container's width, aligned to the containing block's start edge.
    func markswiftFraction(_ fraction: CGFloat, right: Bool = false) -> some View {
        MarkswiftFraction(fraction: fraction, right: right) { self }
    }
}


/// CSS flex row: grow / shrink / basis (px, nil = content, or a fraction of the row), min/max clamps, gaps; no wrap.
struct MarkswiftFlexRow: Layout {
    struct Item: Sendable {
        var grow: CGFloat
        var shrink: CGFloat
        var basis: CGFloat?
        var min: CGFloat = 0
        var max: CGFloat? = nil
        /// Horizontal padding and border: the box's floor, excluded from the shrink weight.
        var inset: CGFloat = 0
        /// Percentage basis: `basis + fraction × width`.
        var fraction: CGFloat? = nil
    }
    enum Align: Sendable { case start, center, end, stretch }
    var items: [Item]
    var spacing: CGFloat
    var align: Align = .stretch

    /// Pure allocation, the CSS flex freeze loop; `MarkswiftFlexRow.widths` and `solveFlexRow`
    /// (src/analysis/flex-row.ts) must agree.
    static func widths(width: CGFloat, items: [Item], bases: [CGFloat], spacing: CGFloat) -> [CGFloat] {
        func clamp(_ v: CGFloat, _ i: Int) -> CGFloat {
            Swift.max(items[i].min, items[i].inset, Swift.min(items[i].max ?? .infinity, v))
        }
        let base = bases.indices.map { i in
            items[i].fraction.map { Swift.max(items[i].inset, bases[i] + $0 * width) } ?? bases[i]
        }
        let space = width - CGFloat(Swift.max(0, items.count - 1)) * spacing
        let growing = base.indices.map { clamp(base[$0], $0) }.reduce(0, +) < space
        let factor = items.map { growing ? $0.grow : $0.shrink }
        let weight = items.indices.map { growing ? items[$0].grow : items[$0].shrink * Swift.max(0, base[$0] - items[$0].inset) }
        var size = base.indices.map { clamp(base[$0], $0) }
        var frozen = base.indices.map { factor[$0] == 0 || (growing ? base[$0] > size[$0] : base[$0] < size[$0]) }
        func left() -> CGFloat { space - base.indices.map { frozen[$0] ? size[$0] : base[$0] }.reduce(0, +) }
        let initial = left()
        // Each pass freezes at least one item; the bound only stops a non-finite measure from looping.
        for _ in 0...items.count where frozen.contains(false) {
            var free = left()
            let open = items.indices.filter { !frozen[$0] }
            let factors = open.map { factor[$0] }.reduce(0, +)
            if factors < 1 && abs(initial * factors) < abs(free) { free = initial * factors }
            let total = open.map { weight[$0] }.reduce(0, +)
            let violation = open.map { i in
                let target = base[i] + (total > 0 ? free * weight[i] / total : 0)
                size[i] = clamp(target, i)
                return size[i] - target
            }
            let sum = violation.reduce(0, +)
            for (k, i) in open.enumerated() where abs(sum) < 0.000001 || (sum > 0 ? violation[k] > 0 : violation[k] < 0) {
                frozen[i] = true
            }
        }
        return size
    }

    private func bases(_ subviews: Subviews) -> [CGFloat] {
        precondition(items.count == subviews.count, "MarkswiftFlexRow items/subviews mismatch")
        return subviews.indices.map { items[$0].basis ?? subviews[$0].sizeThatFits(.unspecified).width }
    }

    private func heights(_ w: [CGFloat], _ height: CGFloat?, _ subviews: Subviews) -> [CGFloat] {
        subviews.indices.map { subviews[$0].sizeThatFits(ProposedViewSize(width: w[$0], height: height)).height }
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let b = bases(subviews)
        // Without a width a percentage basis is indefinite: CSS sizes that item by its content.
        let ideal = subviews.indices.map { items[$0].fraction == nil ? b[$0] : subviews[$0].sizeThatFits(.unspecified).width }
        let width = proposal.width.flatMap { $0.isFinite ? max(0, $0) : nil }
            ?? ideal.reduce(0, +) + CGFloat(max(0, b.count - 1)) * spacing
        let w = Self.widths(width: width, items: items, bases: b, spacing: spacing)
        return CGSize(width: width, height: heights(w, proposal.height, subviews).max() ?? 0)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let w = Self.widths(width: bounds.width, items: items, bases: bases(subviews), spacing: spacing)
        let h = align == .stretch ? [] : heights(w, proposal.height, subviews)
        var x = bounds.minX
        for i in subviews.indices {
            let y = switch align {
            case .start, .stretch: bounds.minY
            case .center: bounds.minY + (bounds.height - h[i]) / 2
            case .end: bounds.maxY - h[i]
            }
            subviews[i].place(at: CGPoint(x: x, y: y), anchor: .topLeading,
                              proposal: ProposedViewSize(width: w[i], height: align == .stretch ? bounds.height : h[i]))
            x += w[i] + spacing
        }
    }
}

/// CSS `fit-content` width: the content's ideal width, never wider than offered. App mode gives it to a box that hugs
/// its content in CSS but holds filling children, which would otherwise take every point a stack offers; unlike the
/// captured width it widens and narrows with native (Dynamic Type) text.
struct MarkswiftFitWidth: Layout {
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let child = subviews.first else { return .zero }
        let ideal = child.sizeThatFits(.unspecified).width
        return child.sizeThatFits(ProposedViewSize(width: min(ideal, proposal.width ?? ideal), height: proposal.height))
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        subviews.first?.place(at: bounds.origin, proposal: ProposedViewSize(bounds.size))
    }
}

extension View {
    func markswiftFitWidth() -> some View { MarkswiftFitWidth { self } }
}


/// A `table-layout: fixed` column: border-box px, a fraction of the available width plus the cell's
/// horizontal padding and border, or an equal share of what is left.
enum MarkswiftTableColumn: Sendable { case px(CGFloat), percent(CGFloat, plus: CGFloat), auto }

/// A CSS table. Every subview carries `.markswiftGridCell(column:row:columnSpan:rowSpan:)` (1-based,
/// tracks.swift); the first `bands` subviews paint row groups and rows and are never measured (under the cells; a
/// band that only draws collapsed borders carries `.zIndex(1)` and draws over them, as CSS paints borders last).
/// `border-spacing` surrounds every column and row, outer edges included.
// ponytail: no Layout cache, cells are measured on every pass; add one if large tables profile slow.
struct MarkswiftTable: Layout {
    /// Captured column border-box widths; without `fixed` they scale to the offered width (auto layout).
    var widths: [CGFloat]
    /// Captured row heights: floors; a row grows to its tallest single-row cell.
    var heights: [CGFloat]
    var hSpacing: CGFloat = 0
    var vSpacing: CGFloat = 0
    var bands: Int = 0
    var fixed: [MarkswiftTableColumn]? = nil

    /// Pure column solver; `solveTableColumns` (src/analysis/table.ts) must agree.
    static func columns(width: CGFloat?, widths: [CGFloat], spacing: CGFloat, fixed: [MarkswiftTableColumn]?) -> [CGFloat] {
        let gaps = CGFloat(widths.count + 1) * spacing
        let natural = widths.reduce(0, +)
        let avail = max(0, (width ?? natural + gaps) - gaps)
        guard let fixed else {
            return widths.map { natural > 0 ? $0 * avail / natural : avail / CGFloat(max(1, widths.count)) }
        }
        let base: [CGFloat] = fixed.map {
            switch $0 {
            case .px(let px): px
            case .percent(let fraction, let plus): fraction * avail + plus
            case .auto: 0
            }
        }
        let autos = fixed.filter { if case .auto = $0 { true } else { false } }.count
        let left = avail - base.reduce(0, +)
        if autos > 0 {
            return zip(fixed, base).map { column, b in if case .auto = column { max(0, left / CGFloat(autos)) } else { b } }
        }
        let sum = base.reduce(0, +)
        return left > 0 && sum > 0 ? base.map { $0 + left * $0 / sum } : base
    }

    private static func span(_ sizes: [CGFloat], _ first: Int, _ count: Int, _ gap: CGFloat) -> CGFloat {
        let lo = min(max(0, first), sizes.count), hi = min(sizes.count, lo + max(1, count))
        return hi > lo ? sizes[lo..<hi].reduce(0, +) + CGFloat(hi - lo - 1) * gap : 0
    }

    private func slot(_ s: LayoutSubview) -> MarkswiftGridCell {
        s[MarkswiftGridCellKey.self] ?? MarkswiftGridCell(column: 1, row: 1)
    }

    private func rows(_ cols: [CGFloat], _ subviews: Subviews) -> [CGFloat] {
        var rows = heights
        let cells = subviews.dropFirst(bands).map { (slot($0), $0) }
        func need(_ c: MarkswiftGridCell, _ s: LayoutSubview) -> CGFloat {
            s.sizeThatFits(ProposedViewSize(width: Self.span(cols, c.column - 1, c.columnSpan, hSpacing), height: nil)).height
        }
        for (c, s) in cells where c.rowSpan == 1 && c.row >= 1 && c.row <= rows.count {
            rows[c.row - 1] = max(rows[c.row - 1], need(c, s))
        }
        // ponytail: a rowspan cell taller than its rows grows only its last row; CSS spreads the excess over them.
        for (c, s) in cells where c.rowSpan > 1 && c.row >= 1 && c.row <= rows.count {
            let last = min(rows.count, c.row - 1 + c.rowSpan) - 1
            let excess = need(c, s) - Self.span(rows, c.row - 1, c.rowSpan, vSpacing)
            if excess > 0 { rows[last] += excess }
        }
        return rows
    }

    private func solve(_ width: CGFloat?, _ subviews: Subviews) -> ([CGFloat], [CGFloat]) {
        let w = width.flatMap { $0.isFinite ? $0 : nil }
        let cols = Self.columns(width: w, widths: widths, spacing: hSpacing, fixed: fixed)
        return (cols, rows(cols, subviews))
    }

    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let (cols, rows) = solve(proposal.width, subviews)
        return CGSize(width: cols.reduce(0, +) + CGFloat(cols.count + 1) * hSpacing,
                      height: rows.reduce(0, +) + CGFloat(rows.count + 1) * vSpacing)
    }

    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        let (cols, rows) = solve(bounds.width, subviews)
        for s in subviews {
            let c = slot(s)
            let x = bounds.minX + CGFloat(c.column) * hSpacing + cols.prefix(max(0, c.column - 1)).reduce(0, +)
            let y = bounds.minY + CGFloat(c.row) * vSpacing + rows.prefix(max(0, c.row - 1)).reduce(0, +)
            s.place(at: CGPoint(x: x, y: y), anchor: .topLeading,
                    proposal: ProposedViewSize(width: Self.span(cols, c.column - 1, c.columnSpan, hSpacing),
                                               height: Self.span(rows, c.row - 1, c.rowSpan, vSpacing)))
        }
    }
}


/// A CSS width breakpoint as the component root sees it: `atLeast` (`min-width`, `>=`) or `above` (`max-width`, `>`).
enum MarkswiftBandEdge: Sendable {
    case atLeast(CGFloat), above(CGFloat)
    /// Narrowest proposal that passes the edge: exactly `px`, or the next representable width above it.
    var minWidth: CGFloat {
        switch self {
        case .atLeast(let px): px
        case .above(let px): px.nextUp
        }
    }
}

extension EnvironmentValues {
    /// The width band `MarkswiftBands` chose; extracted row subviews read it.
    @Entry var markswiftBand: Int = 0
}

/// One ViewThatFits candidate: fits only when the offered width passes `minWidth`; never measures its content otherwise.
struct MarkswiftBandCandidate: Layout {
    let minWidth: CGFloat
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let child = subviews.first else { return .zero }
        guard let w = proposal.width, w.isFinite, w >= minWidth else { return CGSize(width: minWidth, height: 0) }
        return CGSize(width: w, height: child.sizeThatFits(ProposedViewSize(width: w, height: proposal.height)).height)
    }
    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        subviews.first?.place(at: bounds.origin, anchor: .topLeading, proposal: ProposedViewSize(bounds.size))
    }
}

/// Layout-time band selection: the widest band whose edge the proposed width passes; band 0 always fits.
struct MarkswiftBands<Content: View>: View {
    let edges: [MarkswiftBandEdge]
    @ViewBuilder let content: (Int) -> Content
    var body: some View {
        ViewThatFits(in: .horizontal) {
            ForEach(Array(edges.indices.reversed()), id: \.self) { i in
                MarkswiftBandCandidate(minWidth: edges[i].minWidth) { content(i + 1).environment(\.markswiftBand, i + 1) }
            }
            content(0).environment(\.markswiftBand, 0)
        }
    }
}


/// CSS counter styles a list marker is regenerated in; `counterText` (src/css/counter.ts) is the TS mirror.
nonisolated enum MarkswiftCounterStyle: Sendable { case decimal, decimalLeadingZero, lowerAlpha, upperAlpha, lowerRoman, upperRoman }

/// A counter value as Chrome prints it (alphabetic below 1 and roman outside 1…3999 fall back to decimal).
nonisolated func markswiftCounter(_ value: Int, _ style: MarkswiftCounterStyle) -> String {
    switch style {
    case .decimalLeadingZero:
        return value >= 0 && value < 10 ? "0\(value)" : String(value)
    case .lowerAlpha where value >= 1, .upperAlpha where value >= 1:
        var s = ""
        var k = value
        while k > 0 {
            s = String(UnicodeScalar(UInt8(97 + (k - 1) % 26))) + s
            k = (k - 1) / 26
        }
        return style == .upperAlpha ? s.uppercased() : s
    case .lowerRoman where (1...3999).contains(value), .upperRoman where (1...3999).contains(value):
        let pairs: [(Int, String)] = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L"), (40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
        var s = ""
        var k = value
        for (n, r) in pairs {
            while k >= n { s += r; k -= n }
        }
        return style == .lowerRoman ? s.lowercased() : s
    default:
        return String(value)
    }
}


/// CSS `steps()` jump positions.
nonisolated enum MarkswiftStepPosition: Sendable, Hashable { case start, end, none, both }

/// A CSS easing function evaluated exactly: cubic-bezier (and its keywords), steps(), linear() points.
nonisolated enum MarkswiftEase: Sendable, Hashable {
    case bezier(Double, Double, Double, Double)
    case steps(Int, MarkswiftStepPosition)
    /// linear(): output values at input positions (0…1, ascending).
    case points([Double], [Double])

    func callAsFunction(_ u: Double) -> Double {
        switch self {
        case let .bezier(x1, y1, x2, y2):
            return UnitCurve.bezier(startControlPoint: UnitPoint(x: x1, y: y1), endControlPoint: UnitPoint(x: x2, y: y2)).value(at: u)
        case let .steps(n, position):
            if u >= 1 { return 1 }
            let (jumps, lead): (Double, Double) = switch position {
                case .start: (Double(n), 1)
                case .end: (Double(n), 0)
                case .none: (Double(n - 1), 0)
                case .both: (Double(n + 1), 1)
            }
            return min((u * Double(n)).rounded(.down) + lead, jumps) / jumps
        case let .points(outputs, inputs):
            guard let i = inputs.indices.dropFirst().first(where: { inputs[$0] >= u }) else { return outputs.last ?? u }
            let span = inputs[i] - inputs[i - 1]
            return span == 0 ? outputs[i] : outputs[i - 1] + (outputs[i] - outputs[i - 1]) * (u - inputs[i - 1]) / span
        }
    }
}

/// CSS animation timing (web-animations-1 §4): delay, iterations, direction, fill. Times in seconds.
nonisolated struct MarkswiftTiming: Sendable {
    nonisolated enum Direction: Sendable { case normal, reverse, alternate, alternateReverse }
    var duration: Double
    var delay = 0.0
    var iterations = 1.0                      // .infinity = infinite
    var direction = Direction.normal
    var fillBackwards = false
    var fillForwards = false

    /// Iteration progress at `t` seconds since the animation started, nil when no keyframe applies.
    /// `t = .infinity`: finite animations at their fill-forwards end, infinite ones off.
    func progress(at t: Double) -> Double? {
        let active = t - delay, end = duration * iterations
        if active < 0 { return fillBackwards ? directed(0, 0) : nil }
        if active >= end {
            guard fillForwards, end.isFinite else { return nil }
            let whole = iterations.rounded(.down)
            return iterations == whole ? directed(1, max(whole - 1, 0)) : directed(iterations - whole, whole)
        }
        let i = (active / duration).rounded(.down)
        return directed(active / duration - i, i)
    }

    var end: Double { delay + duration * iterations }

    private func directed(_ p: Double, _ iteration: Double) -> Double {
        let odd = iteration.truncatingRemainder(dividingBy: 2) == 1
        switch direction {
        case .normal: return p
        case .reverse: return 1 - p
        case .alternate: return odd ? 1 - p : p
        case .alternateReverse: return odd ? p : 1 - p
        }
    }
}

/// One keyframe interval of a channel: value `to` reached at iteration offset `until`, eased by the interval's own function.
nonisolated struct MarkswiftSegment: Sendable {
    let to: Double, until: Double, ease: MarkswiftEase
    init(_ to: Double, _ until: Double, _ ease: MarkswiftEase) { (self.to, self.until, self.ease) = (to, until, ease) }
}

nonisolated struct MarkswiftMotionTrack: Sendable {
    let from: Double, segments: [MarkswiftSegment]
    init(_ from: Double, _ segments: [MarkswiftSegment]) { (self.from, self.segments) = (from, segments) }

    func value(at p: Double) -> Double {
        var start = 0.0, value = from
        for s in segments {
            if p < s.until, s.until > start { return value + (s.to - value) * s.ease((p - start) / (s.until - start)) }
            (start, value) = (s.until, s.to)
        }
        return value
    }
}

nonisolated struct MarkswiftMotionValue: Sendable, Equatable {
    var opacity = 1.0, x = 0.0, y = 0.0, scaleX = 1.0, scaleY = 1.0, degrees = 0.0
}

/// One CSS animation: its timing and the channels it drives (CSS composite replace).
nonisolated struct MarkswiftMotion: Sendable {
    var timing: MarkswiftTiming
    var opacity: MarkswiftMotionTrack? = nil, x: MarkswiftMotionTrack? = nil, y: MarkswiftMotionTrack? = nil
    var scaleX: MarkswiftMotionTrack? = nil, scaleY: MarkswiftMotionTrack? = nil, degrees: MarkswiftMotionTrack? = nil
    init(_ timing: MarkswiftTiming, opacity: MarkswiftMotionTrack? = nil, x: MarkswiftMotionTrack? = nil, y: MarkswiftMotionTrack? = nil,
         scaleX: MarkswiftMotionTrack? = nil, scaleY: MarkswiftMotionTrack? = nil, degrees: MarkswiftMotionTrack? = nil) {
        (self.timing, self.opacity, self.x, self.y, self.scaleX, self.scaleY, self.degrees) = (timing, opacity, x, y, scaleX, scaleY, degrees)
    }

    func apply(at t: Double, to v: inout MarkswiftMotionValue) {
        guard let p = timing.progress(at: t) else { return }
        if let opacity { v.opacity = opacity.value(at: p) }
        if let x { v.x = x.value(at: p) }
        if let y { v.y = y.value(at: p) }
        if let scaleX { v.scaleX = scaleX.value(at: p) }
        if let scaleY { v.scaleY = scaleY.value(at: p) }
        if let degrees { v.degrees = degrees.value(at: p) }
    }
}

extension EnvironmentValues {
    /// Render harnesses: seconds since appearance for every animation (`.infinity` = the settled look capture uses); nil = live.
    @Entry var markswiftMotionTime: Double? = nil
}

/// CSS `@keyframes` on one view. Live: a TimelineView clock from first appearance (stopped when every finite animation
/// ended); harness: the frame at `markswiftMotionTime`; Reduce Motion: `reduced` (nil = same; empty = the base look).
struct MarkswiftAnimation: ViewModifier {
    let motions: [MarkswiftMotion]
    var reduced: [MarkswiftMotion]? = nil
    /// The settled look (capture's computed values of the driven channels).
    var base = MarkswiftMotionValue()
    var anchor = UnitPoint.center
    @Environment(\.markswiftMotionTime) private var time
    @Environment(\.accessibilityReduceMotion) private var systemReduce
    @Environment(\.markswiftForcedStates) private var forced
    @State private var start = Date.now
    @State private var finished = false

    func body(content: Content) -> some View {
        let active = systemReduce || forced.contains(.reduceMotion) ? reduced ?? motions : motions
        let end = active.map(\.timing.end).max() ?? 0
        if let time {
            frame(content, active, time)
        } else if active.isEmpty || finished {
            frame(content, active, .infinity)
        } else {
            TimelineView(.animation) { context in frame(content, active, context.date.timeIntervalSince(start)) }
                .task(id: end) {
                    guard end.isFinite else { return }
                    try? await Task.sleep(for: .seconds(max(0, end - Date.now.timeIntervalSince(start))))
                    finished = true
                }
        }
    }

    private func frame(_ content: Content, _ motions: [MarkswiftMotion], _ t: Double) -> some View {
        var v = base
        // `.infinity` is the settled look: the captured values exactly, not a recomputed end keyframe.
        if t.isFinite { for m in motions { m.apply(at: t, to: &v) } }
        return content.modifier(MarkswiftMotionFrame(value: v, anchor: anchor))
    }
}

/// Opacity, scale, rotation and offset of one motion frame (CSS `translate · rotate · scale` order).
struct MarkswiftMotionFrame: ViewModifier {
    var value = MarkswiftMotionValue()
    var anchor = UnitPoint.center
    func body(content: Content) -> some View {
        content
            .opacity(value.opacity)
            .scaleEffect(x: value.scaleX, y: value.scaleY, anchor: anchor)
            .rotationEffect(.degrees(value.degrees), anchor: anchor)
            .offset(x: value.x, y: value.y)
    }
}

/// An overlay root's exit frame inside its removal transition; under Reduce Motion (system or harness-forced) the
/// opacity-only `reduced` frame.
struct MarkswiftExitFrame: ViewModifier {
    var value = MarkswiftMotionValue()
    var reduced = MarkswiftMotionValue()
    var anchor = UnitPoint.center
    @Environment(\.accessibilityReduceMotion) private var systemReduce
    @Environment(\.markswiftForcedStates) private var forced
    func body(content: Content) -> some View {
        content.modifier(MarkswiftMotionFrame(value: systemReduce || forced.contains(.reduceMotion) ? reduced : value, anchor: anchor))
    }
}

/// Lays its content out at `fraction` of its height, top-aligned: CSS `height` 0 ↔ auto as a layout change.
struct MarkswiftRevealLayout: Layout {
    var fraction: Double
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        let size = subviews.first?.sizeThatFits(proposal) ?? .zero
        return CGSize(width: size.width, height: size.height * fraction)
    }
    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        subviews.first?.place(at: bounds.origin, anchor: .topLeading, proposal: ProposedViewSize(width: bounds.width, height: nil))
    }
}

/// Disclosure content's insertion/removal: the revealed fraction animates, clipped while partial. `nonisolated`: the
/// `Animatable` conformance must not cross into main-actor code (Swift 6 without MainActor default isolation).
nonisolated struct MarkswiftReveal: ViewModifier, Animatable {
    var fraction: Double
    var animatableData: Double { get { fraction } set { fraction = newValue } }
    func body(content: Content) -> some View {
        if fraction < 1 { MarkswiftRevealLayout(fraction: fraction) { content }.clipped() } else { content }
    }
}

/// CSS steps()/linear() timing for a SwiftUI transition (cubic-bezier uses `Animation.timingCurve`).
nonisolated struct MarkswiftEasing: CustomAnimation {
    let duration: Double
    let ease: MarkswiftEase
    func animate<V: VectorArithmetic>(value: V, time: TimeInterval, context: inout AnimationContext<V>) -> V? {
        time < duration ? value.scaled(by: ease(time / duration)) : nil
    }
}

/// A pressed/focused look's CSS transition: the new state's timing (CSS uses the new style's transition); under
/// Reduce Motion (system or harness-forced) the reduced pair, which the converter already resolved.
struct MarkswiftStateAnimation: ViewModifier {
    let isOn: Bool
    let into: Animation?, back: Animation?, reducedInto: Animation?, reducedBack: Animation?
    @Environment(\.accessibilityReduceMotion) private var systemReduce
    @Environment(\.markswiftForcedStates) private var forced

    func body(content: Content) -> some View {
        let reduce = systemReduce || forced.contains(.reduceMotion)
        content.animation(isOn ? (reduce ? reducedInto : into) : (reduce ? reducedBack : back), value: isOn)
    }
}


/// Where a drawn presentation's content sits inside the component frame.
enum MarkswiftPlacement: Sendable {
    case center, edge(Edge), offset(CGSize)
    case anchored(String, from: UnitPoint, to: UnitPoint, gap: CGSize)
}

struct MarkswiftAnchorKey: PreferenceKey {
    static let defaultValue: [String: Anchor<CGRect>] = [:]
    static func reduce(value: inout [String: Anchor<CGRect>], nextValue: () -> [String: Anchor<CGRect>]) {
        value.merge(nextValue()) { $1 }
    }
}

private struct MarkswiftAnchorsKey: EnvironmentKey { static let defaultValue: [String: CGRect] = [:] }
extension EnvironmentValues {
    var markswiftAnchors: [String: CGRect] {
        get { self[MarkswiftAnchorsKey.self] }
        set { self[MarkswiftAnchorsKey.self] = newValue }
    }
}

private struct MarkswiftPlaced: ViewModifier {
    let placement: MarkswiftPlacement
    @Environment(\.markswiftAnchors) private var anchors
    func body(content: Content) -> some View {
        switch placement {
        case .center: content.frame(maxWidth: .infinity, maxHeight: .infinity)
        case .edge(let e):
            content.frame(maxWidth: .infinity, maxHeight: .infinity,
                          alignment: e == .bottom ? .bottom : e == .top ? .top : e == .leading ? .leading : .trailing)
        case .offset(let o): content.offset(x: o.width, y: o.height)
        case .anchored(let id, let from, let to, let gap):
            let r = anchors[id] ?? .zero
            content
                .alignmentGuide(.leading) { d in d.width * to.x - (r.minX + r.width * from.x + gap.width) }
                .alignmentGuide(.top) { d in d.height * to.y - (r.minY + r.height * from.y + gap.height) }
        }
    }
}

extension View {
    func markswiftAnchor(_ id: String) -> some View {
        anchorPreference(key: MarkswiftAnchorKey.self, value: .bounds) { [id: $0] }
    }
    func markswiftPlaced(_ placement: MarkswiftPlacement) -> some View { modifier(MarkswiftPlaced(placement: placement)) }
    /// A presentation drawn over the component while `isPresented`; the screen owns the state.
    /// The container stays while closed so each root's own removal transition plays; `exit` animates the
    /// runtime's own dismissal (Escape, an outside tap).
    func markswiftPresentation<C: View>(
        isPresented: Binding<Bool>, modal: Bool, dismissOnEscape: Bool, dismissOnOutside: Bool, exit: Animation? = nil,
        onDismiss: @escaping () -> Void, @ViewBuilder content: @escaping () -> C
    ) -> some View {
        overlayPreferenceValue(MarkswiftAnchorKey.self) { anchors in
            GeometryReader { proxy in
                let shown = isPresented.wrappedValue
                let dismiss = { withAnimation(exit) { isPresented.wrappedValue = false }; onDismiss() }
                ZStack(alignment: .topLeading) {
                    if shown {
                        // The full-size base the placements align to (a ZStack aligns its children to one another).
                        // It takes the taps outside the content only when they must not reach the page.
                        Color.clear.contentShape(Rectangle())
                            .onTapGesture { if dismissOnOutside { dismiss() } }
                            .allowsHitTesting(modal || dismissOnOutside)
                            .accessibilityHidden(true)
                        content()
                    }
                }
                .frame(width: proxy.size.width, height: proxy.size.height, alignment: .topLeading)
                .environment(\.markswiftAnchors, anchors.mapValues { proxy[$0] })
                .accessibilityElement(children: .contain)
                .accessibilityAddTraits(modal && shown ? .isModal : [])
                .accessibilityHidden(!shown)
                .accessibilityAction(.escape) { if shown && dismissOnEscape { dismiss() } }
                .onKeyPress(.escape) { guard shown && dismissOnEscape else { return .ignored }; dismiss(); return .handled }
                .allowsHitTesting(shown)
            }
        }
    }
}

/// Resolves CSS percentage/calc width before asking the content for its wrapping height.
struct MarkswiftPresentationWidth: Layout {
    let fraction: CGFloat
    let offset: CGFloat
    let minimum: CGFloat
    let maximum: CGFloat
    func width(_ offered: CGFloat?) -> CGFloat? {
        offered.map { max(minimum, min(maximum, max(0, $0 * fraction + offset))) }
    }
    func sizeThatFits(proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) -> CGSize {
        guard let child = subviews.first else { return .zero }
        let w = width(proposal.width)
        let size = child.sizeThatFits(ProposedViewSize(width: w, height: nil))
        return CGSize(width: w ?? size.width, height: size.height)
    }
    func placeSubviews(in bounds: CGRect, proposal: ProposedViewSize, subviews: Subviews, cache: inout ()) {
        subviews.first?.place(at: bounds.origin, proposal: ProposedViewSize(width: bounds.width, height: nil))
    }
}
